// Package highlight marks up the text of a previewed file as the language its
// name implies.
//
// Chroma owns the languages: its lexers decide what a token is, so nothing here
// lists a syntax. The markup carries class names rather than colours, and the
// stylesheet behind those classes is generated by ./generate from the shared
// palette, so a preview is coloured like the rest of the window.
package highlight

import (
	"strings"

	"github.com/alecthomas/chroma/v2"
	"github.com/alecthomas/chroma/v2/formatters/html"
	"github.com/alecthomas/chroma/v2/lexers"
	"github.com/alecthomas/chroma/v2/styles"
)

//go:generate go run ./generate -out ../../frontend/src/highlight.css

// ClassPrefix guards chroma's class names, which are single letters, against
// everything else the frontend's stylesheet holds. The generator needs it too,
// so the markup and the sheet cannot drift apart.
const ClassPrefix = "hl-"

// The pane brings its own <pre>, so the formatter must not add one.
var formatter = html.New(
	html.WithClasses(true),
	html.ClassPrefix(ClassPrefix),
	html.PreventSurroundingPre(true),
)

// HTML returns source marked up as HTML, or an empty string for a file no lexer
// covers, which leaves the caller with the plain text it already had. The token
// text is escaped, so the result is safe to insert as markup.
func HTML(fileName string, source string) string {
	lexer := lexers.Match(fileName)
	if lexer == nil {
		return ""
	}
	iterator, err := chroma.Coalesce(lexer).Tokenise(nil, source)
	if err != nil {
		return ""
	}
	return format(iterator)
}

// The style is what a formatter writing colours would draw with; one writing
// class names never reads it.
func format(iterator chroma.Iterator) string {
	marked := strings.Builder{}
	if err := formatter.Format(&marked, styles.Fallback, iterator); err != nil {
		return ""
	}
	return marked.String()
}
